import java.sql.*; public class CheckAdmin { public static void main(String[] args) throws Exception { String url = "jdbc:postgresql://localhost:5432/sales_management"; String user = "postgres"; String password = "postgres"; try (Connection conn = DriverManager.getConnection(url, user, password); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery("SELECT id, email, password_hash, active, locked FROM users WHERE email = 'admin@knoweb.lk'")) { if (rs.next()) { System.out.println("Email: " + rs.getString("email")); System.out.println("Password Hash: " + rs.getString("password_hash")); System.out.println("Is Active: " + rs.getBoolean("active")); System.out.println("Is Locked: " + rs.getBoolean("locked")); } else { System.out.println("Admin user not found."); } } catch (Exception e) { e.printStackTrace(); } } }